function disable_img_interaction(e){let t=document.getElementById(e);t.style.pointerEvents="none"}function get_copyright(){let e=2024,t=document.getElementById("copyright-year");const n=new Date;let o=n.getFullYear();t.innerHTML=o>e?`© ${e}-${o}`:`© ${o}`}function enable_tooltips(){const e=document.querySelectorAll('[data-bs-toggle="tooltip"]');[...e].map(e=>new bootstrap.Tooltip(e))}function toggle_mode_initialize(){let e=localStorage.getItem("web-mode");null===e&&localStorage.setItem("web-mode","light"),e in["light","dark"]&&console.log("working")}document.addEventListener("DOMContentLoaded",e=>setInterval(()=>{let e=document.getElementById("pre-loader");e.classList.contains("hidden")||e.classList.add("hidden")},1e3)),document.addEventListener("DOMContentLoaded",e=>{disable_img_interaction("about-banner")}),document.addEventListener("DOMContentLoaded",e=>{enable_tooltips()}),document.addEventListener("DOMContentLoaded",e=>{get_copyright()}),document.addEventListener("DOMContentLoaded",e=>toggle_mode_initialize());